//! Checks the Rust sim against results saved from sim-3 (tests/fixtures/sim3_results.json,
//! generated by bench/make-fixtures.js). Results must be identical, bit for bit.
//!
//! Exact equality only holds in WebAssembly, where log10/pow are JavaScript's (see
//! src/utils/fastmath.rs), so this runs in Node:
//!   wasm-pack test --node wasm --test sim3_parity
#![cfg(target_arch = "wasm32")]

use serde_json::{Value, json};
use wasm_bindgen_test::wasm_bindgen_test;

const FIXTURES: &str = include_str!("fixtures/sim3_results.json");
const DATA_JSON: &str = include_str!("../../src/Data/data.json");

fn fixtures() -> Value {
    serde_json::from_str(FIXTURES).expect("valid fixture file")
}

fn settings() -> Value {
    json!({
        "dt": 1.5, "ddt": 1.0001, "bought_vars_delta": 5,
        "sim_all_strats": "all", "completed_cts": "no", "show_a23": false, "show_unofficials": false
    })
}

/** Calls the same JSON API as the website and returns the response data */
/** Adds a case's theory inputs (only saved when it has some) to a query */
fn with_inputs(mut data: Value, case: &Value) -> Value {
    if !case["theory_inputs"].is_null() {
        data["theory_inputs"] = case["theory_inputs"].clone();
    }
    data
}

fn api(query_type: &str, mut data: Value) -> Value {
    wasm::set_config(DATA_JSON);
    data["settings"] = settings();
    let res: Value = serde_json::from_str(&wasm::run_query(
        &json!({ "type": query_type, "data": data }).to_string(),
    ))
    .unwrap();
    assert_eq!(
        res["response_type"], "success",
        "API error: {}",
        res["data"]
    );
    res["data"]["data"].clone()
}

/** Converts an API SimResult to the fixture summary format */
fn summary(r: &Value) -> Value {
    json!({
        "strat": r["strat"],
        "tauH": r["tau_h"],
        "pubRho": r["pub_rho"],
        "time": r["time"],
        "boughtVars": r["bought_vars"].as_array().map_or(0, |a| a.len()),
    })
}

/** Returns a description of the differences, if any */
fn diff(label: &str, expected: &Value, actual: &Value) -> Option<String> {
    let mut out = Vec::new();
    for key in ["strat", "tauH", "pubRho", "time", "boughtVars"] {
        let same = match (expected[key].as_f64(), actual[key].as_f64()) {
            (Some(a), Some(b)) => a == b,
            _ => expected[key] == actual[key],
        };
        if !same {
            out.push(format!(
                "{key}: sim-3 {} vs rust {}",
                expected[key], actual[key]
            ));
        }
    }
    (!out.is_empty()).then(|| format!("{label}: {}", out.join(", ")))
}

fn assert_no_failures(failures: Vec<String>, total: usize) {
    assert!(
        failures.is_empty(),
        "{} of {total} cases differ from sim-3:
{}{}",
        failures.len(),
        failures.join(
            "
"
        ),
        node_version_hint()
    );
}

/** Node.js version running the tests, e.g. "v26.12.1" (read from `process.versions.node`) */
fn running_node_version() -> Option<String> {
    let get = |obj: &wasm_bindgen::JsValue, key: &str| js_sys::Reflect::get(obj, &key.into()).ok();
    let version = get(&get(&js_sys::global().into(), "process")?, "versions")
        .and_then(|versions| get(&versions, "node"))?
        .as_string()?;
    Some(format!("v{version}"))
}

/** Node.js version the fixtures were generated with, from their `source` field */
fn fixture_node_version() -> Option<String> {
    let source = fixtures()["source"].as_str()?.to_owned();
    Some(source.split("Node ").nth(1)?.trim().to_owned())
}

fn major(version: &str) -> &str {
    version.split('.').next().unwrap_or(version)
}

/** Explains failures caused by running a different Node major version than the fixtures used */
fn node_version_hint() -> String {
    match (fixture_node_version(), running_node_version()) {
        (Some(f), Some(r)) if major(&f) != major(&r) => format!(
            "

The fixtures were generated with Node {f} but the tests run on Node {r}. JavaScript engines              differ in the last digit of Math.log10/Math.pow, so results are only bit-identical on the same              Node major version: run the tests with Node {} or regenerate the fixtures (bench/make-fixtures.js).",
            major(&f)
        ),
        _ => String::new(),
    }
}

#[wasm_bindgen_test]
fn fixtures_match_the_running_node_version() {
    let fixture = fixture_node_version().expect("fixture source should record the Node version");
    let running = running_node_version().expect("tests should run in Node");
    assert_eq!(major(&fixture), major(&running), "{}", node_version_hint());
}

#[wasm_bindgen_test]
fn named_strats_match_sim3() {
    let f = fixtures();
    let cases = f["strats"].as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let (theory, strat) = (c["theory"].as_str().unwrap(), c["strat"].as_str().unwrap());
        let (sigma, rho) = (
            c["sigma"].as_u64().unwrap() as u32,
            c["rho"].as_f64().unwrap(),
        );
        let inputs = if c["theory_inputs"].is_null() {
            "{}".to_owned()
        } else {
            c["theory_inputs"].to_string()
        };
        let actual: Value = serde_json::from_str(&wasm::sim_strat_with_inputs(
            theory, strat, sigma, rho, &inputs,
        ))
        .unwrap();
        failures.extend(diff(
            &format!("{theory} {strat} e{rho} sigma={sigma}"),
            &c["expected"],
            &actual,
        ));
    }
    assert_no_failures(failures, cases.len());
}

#[wasm_bindgen_test]
fn best_strat_selection_matches_sim3() {
    let f = fixtures();
    let cases = f["best"].as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let data = json!({
            "theory": c["theory"], "strat": c["strat"], "sigma": c["sigma"], "rho": c["rho"],
            "cap": null, "last_strat": null
        });
        let actual = summary(&api("single", with_inputs(data, c))["result"]);
        failures.extend(diff(
            &format!(
                "{} {} e{} sigma={}",
                c["theory"], c["strat"], c["rho"], c["sigma"]
            ),
            &c["expected"],
            &actual,
        ));
    }
    assert_no_failures(failures, cases.len());
}

#[wasm_bindgen_test]
fn chains_match_sim3() {
    let f = fixtures();
    let cases = f["chains"].as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let label = format!(
            "chain {} {} e{}->e{} sigma={}",
            c["theory"], c["strat"], c["rho"], c["cap"], c["sigma"]
        );
        let data = json!({
            "theory": c["theory"], "strat": c["strat"], "sigma": c["sigma"], "rho": c["rho"],
            "cap": c["cap"], "hard_cap": c["hard_cap"]
        });
        let actual = api("chain", with_inputs(data, c));
        let expected = &c["expected"];
        let (exp_results, act_results) = (
            expected["results"].as_array().unwrap(),
            actual["results"].as_array().unwrap(),
        );
        if exp_results.len() != act_results.len() {
            failures.push(format!(
                "{label}: {} pubs in sim-3 vs {} in rust",
                exp_results.len(),
                act_results.len()
            ));
            continue;
        }
        for (i, (e, a)) in exp_results.iter().zip(act_results).enumerate() {
            failures.extend(diff(&format!("{label} pub {i}"), e, &summary(a)));
        }
        for (exp_key, act_key) in [
            ("deltaTau", "delta_tau"),
            ("averageRate", "average_rate"),
            ("totalTime", "total_time"),
        ] {
            if expected[exp_key].as_f64() != actual[act_key].as_f64() {
                failures.push(format!(
                    "{label}: {exp_key} sim-3 {} vs rust {}",
                    expected[exp_key], actual[act_key]
                ));
            }
        }
    }
    assert_no_failures(failures, cases.len());
}

/** Compares two JSON values; numbers must be exactly equal as f64 */
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(x, y)| json_eq(x, y))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).is_some_and(|w| json_eq(v, w)))
        }
        _ => a == b,
    }
}

#[wasm_bindgen_test]
fn other_modes_match_sim3() {
    let f = fixtures();
    let cases = f["modes"].as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let (mode, extra) = (c["mode"].as_str().unwrap(), c["extra"].as_array().unwrap());
        let base = with_inputs(
            json!({ "theory": c["theory"], "strat": c["strat"], "sigma": c["sigma"], "rho": c["rho"] }),
            c,
        );
        let with = |pairs: &[(&str, &Value)]| {
            let mut d = base.clone();
            for (k, v) in pairs {
                d[*k] = (*v).clone();
            }
            d
        };
        let summaries = |r: &Value| {
            Value::Array(
                r["results"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(summary)
                    .collect(),
            )
        };
        let chain_like = |r: &Value| {
            json!({
                "results": summaries(r), "deltaTau": r["delta_tau"], "averageRate": r["average_rate"], "totalTime": r["total_time"]
            })
        };
        let actual = match mode {
            "step" => {
                json!({ "results": summaries(&api("step", with(&[("cap", &extra[0]), ("step", &extra[1])]))) })
            }
            "amount" => chain_like(&api("amount", with(&[("amount", &extra[0])]))),
            "time" => chain_like(&api("time", with(&[("time", &extra[0])]))),
            "step_chain" => {
                json!({ "results": summaries(&api("step_chain", with(&[("cap", &extra[0]), ("step", &extra[1]), ("hard_cap", &extra[2])]))) })
            }
            "comparison" => {
                json!({ "results": summaries(&api("comparison", with_inputs(json!({ "theory": c["theory"], "sigma": c["sigma"], "rho": c["rho"] }), c))) })
            }
            "pub_table" => api(
                "pub_table",
                with(&[("cap", &extra[0]), ("step", &extra[1])]),
            ),
            other => panic!("unknown mode {other}"),
        };
        if !json_eq(&c["expected"], &actual) {
            failures.push(format!(
                "{mode} {} {} e{}: sim-3 {} vs rust {}",
                c["theory"], c["strat"], c["rho"], c["expected"], actual
            ));
        }
    }
    assert_no_failures(failures, cases.len());
}
